<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';
$slug=trim((string)($_GET['slug']??''));$category=null;$products=[];
try{$pdo=db();$q=$pdo->prepare("SELECT id,name,description FROM categories WHERE slug=? AND is_active=1 AND compliance_status='approved' LIMIT 1");$q->execute([$slug]);$category=$q->fetch();if($category){$q=$pdo->prepare("SELECT p.name,p.slug,p.price,p.stock_quantity,p.short_description,(SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY is_primary DESC,sort_order LIMIT 1) image_path FROM products p WHERE p.category_id=? AND p.status='active' AND p.compliance_status='approved' ORDER BY p.created_at DESC");$q->execute([$category['id']]);$products=$q->fetchAll();}}catch(Throwable $e){error_log($e->getMessage());}
?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($category['name']??'القسم غير متاح')?> | الفخامة</title><link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="assets/css/store.css"></head><body><header class="site-header"><div class="container nav-wrap"><a class="brand" href="./"><span class="brand-mark">ف</span><span><strong>الفخامة</strong><small>AL FAKHAMAH</small></span></a><a class="btn btn-outline" href="cart.php">سلة المشتريات</a></div></header><main class="section"><div class="container"><a class="text-link" href="./">الرئيسية /</a><h1><?=e($category['name']??'القسم غير متاح')?></h1><?php if(!$category):?><div class="empty-state"><h3>هذا القسم غير متاح حالياً</h3><a class="btn btn-gold" href="./">العودة للرئيسية</a></div><?php elseif(!$products):?><div class="empty-state"><h3>لا توجد منتجات معتمدة في هذا القسم حالياً</h3></div><?php else:?><div class="product-grid"><?php foreach($products as $p):?><article class="product-card"><a class="product-image" href="product.php?slug=<?=rawurlencode($p['slug'])?>"><?php if($p['image_path']):?><img loading="lazy" src="<?=e($p['image_path'])?>" alt="<?=e($p['name'])?>"><?php else:?><span class="image-placeholder">الفخامة</span><?php endif;?></a><div class="product-info"><h3><?=e($p['name'])?></h3><p><?=e($p['short_description'])?></p><div class="product-bottom"><strong><?=number_format((float)$p['price'],2)?> <small>ر.س</small></strong><span class="<?=((int)$p['stock_quantity']>0?'available':'unavailable')?>"><?=((int)$p['stock_quantity']>0?'متوفر':'غير متوفر')?></span></div><a class="btn btn-outline" href="product.php?slug=<?=rawurlencode($p['slug'])?>">التفاصيل</a></div></article><?php endforeach;?></div><?php endif;?></div></main></body></html>